    /// Recognized leading titles, including titles without a remaining name.
    pub person_titles: Vec<PersonTitle>,
    /// Title-free normalized candidate, retaining name punctuation.
    pub person_name_normalized: Option<String>,
    /// Token sequence without common leading honorifics.
    pub person_core: Option<String>,
    /// Initial letters of the person-core tokens.
    pub person_initials: Option<String>,
    /// Organisation-core initials, excluding listed connective words.
    pub organisation_initials: Option<String>,
    /// A source acronym whose letters agree with an explicit parenthetical expansion.
    pub explicit_acronym: Option<String>,
    /// Normalized expansion validated against the explicit acronym.
    pub acronym_expansion_normalized: Option<String>,
    /// Parenthetical contents in their original spelling and order.
    pub parenthetical_text: Vec<String>,
    /// Names following an explicit trading-as marker, without inferred aliases.
    pub explicit_aliases: Vec<String>,
    /// Normalized forms of those explicit aliases, in the same order.
    pub alias_normalized: Vec<String>,
    /// Literal `and` or ampersand evidence, without claiming multiple entities.
    pub has_conjunction: bool,
    /// At least one unmatched opening or closing parenthesis.
    pub has_unbalanced_parentheses: bool,
}

impl FunderNameFeatures {
    /// Derives parallel features while retaining the original evidence.
    #[must_use]
    pub fn from_name(raw: Option<&str>) -> Self {
        let normalized = raw.map(normalize);
        let name_status = match normalized.as_deref() {
            None | Some("") => NameStatus::Missing,
            Some("confidential" | "withheld" | "name withheld" | "anonymous" | "not disclosed") => {
                NameStatus::Withheld
            }
            Some(_) => NameStatus::Present,
        };
        let (parenthetical_text, has_unbalanced_parentheses) = parentheses(raw.unwrap_or(""));
        let usable = normalized.filter(|_| name_status == NameStatus::Present);
        let name_accent_folded = usable.as_ref().map(|name| {
            name.nfd()
                .filter(|c| !is_combining_mark(*c))
                .collect::<String>()
        });
        let name_tokens = usable.as_deref().map(tokens);
        let has_conjunction = name_tokens
            .as_deref()
            .is_some_and(|name| name.split_whitespace().any(|word| word == "and"));
        let name_token_key = name_tokens.as_deref().map(|name| {
            let mut words = name.split_whitespace().collect::<Vec<_>>();
            words.sort_unstable();
            words.join(" ")
        });
        let primary_name_normalized = raw
            .filter(|_| name_status == NameStatus::Present)
            .map(|raw| normalize(&primary_name(raw)));
        let organisation_core = primary_name_normalized
            .as_deref()
            .map(|name| organisation_core(&tokens(name)));
        let person = usable.as_deref().map(ParsedPersonName::parse);
        let (person_titles, person_name_normalized, person_core) = person.map_or_else(
            || (Vec::new(), None, None),
            |person| (person.titles, person.normalized, Some(person.core)),
        );
        let person_initials = person_core.as_deref().map(|name| initials(name, false));
        let organisation_initials = organisation_core
            .as_deref()
            .map(|name| initials(name, true));
        let (explicit_acronym, acronym_expansion_normalized) = raw
            .and_then(|name| explicit_acronym(name, &parenthetical_text))
            .unzip();
        let explicit_aliases = raw.map_or_else(Vec::new, |name| aliases(name, &parenthetical_text));
        let alias_normalized = explicit_aliases
            .iter()
            .map(|name| normalize(name))
            .collect();
        Self {
            name_raw: raw.map(str::to_owned),
            name_status,
            name_normalized: usable,
            name_accent_folded,
            name_tokens,
            name_token_key,
            primary_name_normalized,
            organisation_core,
            person_titles,
            person_name_normalized,
            person_core,
            person_initials,
            organisation_initials,
            explicit_acronym,
            acronym_expansion_normalized,
            parenthetical_text,
            explicit_aliases,
            alias_normalized,
            has_conjunction,
            has_unbalanced_parentheses,
        }
    }
}

fn normalize(raw: &str) -> String {
    raw.nfkc()
        .flat_map(char::to_lowercase)
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn tokens(name: &str) -> String {
    let mut result = String::new();
    for word in name.split_whitespace() {
        let acronym = word.trim_matches(|c: char| !c.is_alphanumeric() && c != '.');
        let dotted_acronym = acronym.contains('.')
            && acronym.trim_end_matches('.').split('.').all(|part| {
                let mut letters = part.chars();
                letters.next().is_some_and(char::is_alphabetic) && letters.next().is_none()
            });
        for c in word.chars() {
            match c {
                '&' => result.push_str(" and "),
                '\'' | '\u{2019}' | '\u{2018}' | '\u{02bc}' => {}
                '.' if dotted_acronym => {}
                c if c.is_alphanumeric() || is_combining_mark(c) => result.push(c),
                _ => result.push(' '),
            }
        }
        result.push(' ');
    }
    result.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn organisation_core(name: &str) -> String {
    const SUFFIXES: &[&[&str]] = &[
        &["public", "limited", "company"],
        &["community", "interest", "company"],
        &["limited", "liability", "partnership"],
        &["limited", "partnership"],
        &["limited"],
        &["ltd"],
        &["plc"],
        &["llp"],
        &["lp"],
        &["cic"],
    ];
    let mut words = name.split_whitespace().collect::<Vec<_>>();
    if let Some(suffix) = SUFFIXES.iter().find(|suffix| words.ends_with(suffix)) {
        words.truncate(words.len() - suffix.len());
    }
    words.join(" ")
}

fn initials(name: &str, omit_connectives: bool) -> String {
    const CONNECTIVES: &[&str] = &["a", "an", "and", "for", "in", "of", "on", "the", "to"];
    name.split_whitespace()
        .filter(|word| !omit_connectives || !CONNECTIVES.contains(word))
        .filter_map(|word| word.chars().next())
        .collect()
}

fn parentheses(raw: &str) -> (Vec<String>, bool) {
    let mut result = Vec::new();
    let mut depth = 0;
    let mut start = 0;
    let mut unbalanced = false;
    for (index, c) in raw.char_indices() {
        match c {
            '(' => {
                if depth == 0 {
                    start = index + 1;
                }
                depth += 1;
            }
            ')' if depth > 0 => {
                depth -= 1;
                if depth == 0 {
                    result.push(raw[start..index].to_owned());
                }
            }
            ')' => unbalanced = true,
            _ => {}
        }
    }
    if depth > 0 {
        result.push(raw[start..].to_owned());
    }
    (result, unbalanced || depth > 0)
}

fn explicit_acronym(raw: &str, parenthetical: &[String]) -> Option<(String, String)> {
    let before = raw.split('(').next()?.trim();
    for expansion in parenthetical {
        for (candidate, full) in [(before, expansion.as_str()), (expansion.as_str(), before)] {
            let letters = candidate
                .chars()
                .filter(|c| *c != '.' && !c.is_whitespace())
                .collect::<String>();
            if (2..=10).contains(&letters.chars().count())
                && letters.chars().all(|c| c.is_ascii_uppercase())
                && letters.to_lowercase() == initials(&tokens(&normalize(full)), true)
            {
                return Some((letters.to_lowercase(), normalize(full)));
            }
        }
    }
    None
}

fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
    let lower = candidate.to_ascii_lowercase();
    let mut found = None;
    for marker in ["trading as", "t/a"] {
        for (index, _) in lower.match_indices(marker) {
            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
                && lower[index + marker.len()..].starts_with(char::is_whitespace);
            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
                '(' => depth + 1,
                ')' => depth - 1,
                _ => depth,
            });
            if boundary
                && (!top_level_only || depth == 0)
                && found.is_none_or(|(previous, _)| index < previous)
            {
                found = Some((index, marker.len()));
            }
        }
    }
    found
}

fn aliases(raw: &str, parenthetical: &[String]) -> Vec<String> {
    let mut result = Vec::new();
    for (candidate, top_level_only) in parenthetical
        .iter()
        .map(|name| (name.as_str(), false))
        .chain(std::iter::once((raw, true)))
    {
        if let Some((index, length)) = alias_marker(candidate, top_level_only) {
            let alias = candidate[index + length..].trim().to_owned();
            if !alias.is_empty() && !result.contains(&alias) {
                result.push(alias);
            }
        }
    }
    result
}

fn primary_name(raw: &str) -> String {
    let mut result = String::new();
    let mut depth = 0;
    let mut start = 0;
    let mut keep_from = 0;
    for (index, c) in raw.char_indices() {
        match c {
            '(' => {
                if depth == 0 {
                    start = index;
                }
                depth += 1;
            }
            ')' if depth > 0 => {
                depth -= 1;
                if depth == 0 && alias_marker(&raw[start + 1..index], false).is_some() {
                    result.push_str(&raw[keep_from..start]);
                    result.push(' ');
                    keep_from = index + 1;
                }
            }
            _ => {}
        }
    }
    result.push_str(&raw[keep_from..]);
    if let Some((index, _)) = alias_marker(&result, true) {
        result.truncate(index);
    }
    result.trim().trim_end_matches(',').trim().to_owned()
}

#[cfg(test)]
mod tests;
"}

item.aggregated_output:
use super::identity::{company, individual_donor_name};
use super::{
    AddressMatchQuality, BTreeMap, BTreeSet, EntityIngestionError, FunderObservationId, FunderRole,
    FundingEntryId, invalid,
};
use crate::domain::models::{
    declaration_cleaning::SourceScope, declaration_ingestion::DeclarationId,
    parliament_member::MemberId,
};
use serde::Deserialize;
#[derive(Clone, Debug, Deserialize)]
pub struct Observation {
    pub funder_id: FunderObservationId,
    #[serde(rename = "parliament_member_id")]
    pub member_id: MemberId,
    pub declaration_id: DeclarationId,
    pub register_id: u32,
    pub role: FunderRole,
    pub source_scope: String,
    pub source_pointer: String,
    pub funding_entry_id: Option<FundingEntryId>,
    pub funding_ordinal: Option<u32>,
    pub donor_kind: Option<String>,
    pub donor_company_number: Option<String>,
    pub name_raw: Option<String>,
    pub name_normalized: Option<String>,
    pub person_name_normalized: Option<String>,
    pub organisation_core: Option<String>,
    pub alias_normalized: Vec<String>,
    pub address_normalized: Option<String>,
    pub address_match_quality: AddressMatchQuality,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Payment {
    pub funding_entry_id: FundingEntryId,
    #[serde(rename = "parliament_member_id")]
    pub member_id: MemberId,
    pub declaration_id: DeclarationId,
    pub register_id: u32,
    pub funding_ordinal: u32,
    pub parent_declaration_id: Option<DeclarationId>,
    pub is_ultimate_payer_different: Option<bool>,
    pub donor_funder_id: Option<FunderObservationId>,
    pub payer_funder_id: Option<FunderObservationId>,
    pub ultimate_payer_funder_id: Option<FunderObservationId>,
}

/// Cleaned evidence whose identity and role references have been checked together.
pub struct ResolutionInput {
    pub(crate) observations: BTreeMap<FunderObservationId, Observation>,
    pub(crate) payments: BTreeMap<FundingEntryId, Payment>,
    pub(crate) digests: BTreeMap<String, String>,
}

impl ResolutionInput {
    pub(crate) fn new(
        observations: Vec<Observation>,
        payments: Vec<Payment>,
        digests: BTreeMap<String, String>,
    ) -> Result<Self, EntityIngestionError> {
        let mut input = Self {
            observations: BTreeMap::new(),
            payments: BTreeMap::new(),
            digests,
        };
        let mut declarations = BTreeMap::new();
        for payment in payments {
            check_payment(&payment, &mut declarations)?;
            if input
                .payments
                .insert(payment.funding_entry_id.clone(), payment)
                .is_some()
            {
                return Err(invalid("duplicate funding occurrence ID"));
            }
        }
        for observation in observations {
            check_observation(&observation, &input, &mut declarations)?;
            if input
                .observations
                .insert(observation.funder_id.clone(), observation)
                .is_some()
            {
                return Err(invalid("duplicate funder observation ID"));
            }
        }
        for payment in input.payments.values() {
            for (id, role) in [
                (&payment.donor_funder_id, FunderRole::Donor),
                (&payment.payer_funder_id, FunderRole::Payer),
                (&payment.ultimate_payer_funder_id, FunderRole::UltimatePayer),
            ] {
                if let Some(id) = id {
                    let observation = input
                        .observations
                        .get(id)
                        .ok_or_else(|| invalid("dangling payment role reference"))?;
                    if observation.role != role
                        || observation.funding_entry_id.as_ref() != Some(&payment.funding_entry_id)
                    {
                        return Err(invalid("payment role points to unrelated observation"));
                    }
                }
            }
        }
        for observation in input.observations.values() {
            if let Some(id) = &observation.funding_entry_id {
                let payment = &input.payments[id];
                let role_id = match observation.role {
                    FunderRole::Donor => &payment.donor_funder_id,
                    FunderRole::Payer => &payment.payer_funder_id,
                    FunderRole::UltimatePayer => &payment.ultimate_payer_funder_id,
                };
                if role_id.as_ref() != Some(&observation.funder_id) {
                    return Err(invalid("unreferenced funding role observation"));
                }
            }
        }
        Ok(input)
    }

    /// Groups repeated feature profiles without asserting that they identify the same funder.
    #[must_use]
    pub fn scoring_input(&self, candidate_budget: usize) -> ScoringInput {
        let mut groups = BTreeMap::<(String, Option<String>), Vec<FunderObservationId>>::new();
        for observation in self.observations.values() {
            if let Some(name) = &observation.name_normalized {
                groups
                    .entry((name.clone(), observation.address_normalized.clone()))
                    .or_default()
                    .push(observation.funder_id.clone());
            }
        }
        let mut rows = Vec::new();
        let mut members = BTreeMap::new();
        for (index, ((name, address), ids)) in groups.into_iter().enumerate() {
            let key = format!("profile-{index:08}");
            rows.push(ComparisonRow {
                key: key.clone(),
                name: name.clone(),
                address: address.clone(),
                blocking_keys: ids
                    .iter()
                    .flat_map(|id| blocking_keys(&self.observations[id]))
                    .collect::<BTreeSet<_>>()
                    .into_iter()
                    .collect(),
                needs_resolution: ids
                    .iter()
                    .any(|id| company(&self.observations[id]).is_none()),
            });
            members.insert(key.clone(), ids.clone());
            if ids.len() > 1
                && ids
                    .iter()
                    .any(|id| company(&self.observations[id]).is_none())
            {
                let copy = format!("{key}-repeat");
                rows.push(ComparisonRow {
                    key: copy.clone(),
                    name,
                    address,
                    blocking_keys: ids
                        .iter()
                        .flat_map(|id| blocking_keys(&self.observations[id]))
                        .collect::<BTreeSet<_>>()
                        .into_iter()
                        .collect(),
                    needs_resolution: true,
                });
                members.insert(copy, ids);
            }
        }
        ScoringInput {
            candidate_budget,
            rows,
            members,
        }
    }
}

fn blocking_keys(observation: &Observation) -> BTreeSet<String> {
    let mut keys = observation
        .name_normalized
        .iter()
        .chain(observation.alias_normalized.iter())
        .map(|name| format!("funder-name:{name}"))
        .collect::<BTreeSet<_>>();
    if let Some(name) = individual_donor_name(observation) {
        keys.insert(format!("individual-donor-name:{name}"));
    }
    let is_trade_union = observation
        .donor_kind
        .as_deref()
        .is_some_and(|kind| kind.trim().eq_ignore_ascii_case("trade union"));
    let Some(raw) = observation.name_raw.as_deref() else {
        return keys;
    };
    let raw = raw.to_lowercase();
    if is_trade_union
        && raw
            .split(|c: char| !c.is_alphanumeric())
            .any(|token| token == "unite")
    {
        keys.insert("trade-union:unite".to_owned());
    }
    keys
}

fn root_scope(pointer: &str) -> bool {
    let parts = pointer.split('/').collect::<Vec<_>>();
    parts.len() >= 4
        && parts[0].is_empty()
        && parts[1] == "versions"
        && parts[2].parse::<u32>().is_ok()
        && parts[3] == "fields"
        && (parts.len() - 4).is_multiple_of(3)
        && parts[4..].chunks(3).all(|chunk| {
            chunk[0].parse::<u32>().is_ok()
                && chunk[1] == "values"
                && chunk[2].parse::<u32>().is_ok()
        })
}
pub(super) fn is_root(pointer: &str) -> bool {
    pointer.split('/').count() == 4
}

/// Feature profiles supplied to the statistical scorer.
pub struct ScoringInput {
    pub(crate) candidate_budget: usize,
    pub(crate) rows: Vec<ComparisonRow>,
    pub(super) members: BTreeMap<String, Vec<FunderObservationId>>,
}
#[derive(Clone)]
#[cfg_attr(test, derive(Deserialize))]
pub struct ComparisonRow {
    pub key: String,
    pub name: String,
    pub address: Option<String>,
    pub blocking_keys: Vec<String>,
    pub needs_resolution: bool,
}

/// Validated model scores, with provenance supplied by the scoring runtime.
pub struct ScoredPairs {
    pub(crate) pairs: Vec<ScoredPair>,
    pub(crate) model: serde_json::Value,
}
#[derive(Deserialize)]
pub struct ScoredPair {
    pub left: String,
    pub right: String,
    pub probability: f64,
    pub name_level: i32,
    pub address_level: i32,
}
impl ScoredPairs {
    pub(crate) fn checked(
        pairs: Vec<ScoredPair>,
        model: serde_json::Value,
        input: &ScoringInput,
    ) -> Result<Self, EntityIngestionError> {
        let mut seen = BTreeSet::new();
        if pairs.len() > input.candidate_budget {
            return Err(invalid("scorer exceeded candidate budget"));
        }
        for pair in &pairs {
            if pair.left >= pair.right
                || !input.members.contains_key(&pair.left)
                || !input.members.contains_key(&pair.right)
                || !seen.insert((&pair.left, &pair.right))
            {
                return Err(invalid(
                    "scorer returned duplicate, unordered, or unknown profile pair",
                ));
            }
            if !pair.probability.is_finite()
                || !(0.0..=1.0).contains(&pair.probability)
                || !(-1..=2).contains(&pair.name_level)
                || !(-1..=1).contains(&pair.address_level)
            {
                return Err(invalid(
                    "scorer returned invalid probability or comparison level",
                ));
            }
        }
        Ok(Self { pairs, model })
    }
}

type DeclarationMetadata = BTreeMap<(MemberId, DeclarationId), (u32, Option<DeclarationId>)>;
fn check_payment(
    payment: &Payment,
    declarations: &mut DeclarationMetadata,
) -> Result<(), EntityIngestionError> {
    if payment.register_id == 0 {
        return Err(invalid("zero register identity"));
    }
    let metadata = (payment.register_id, payment.parent_declaration_id);
    if declarations
        .insert((payment.member_id, payment.declaration_id), metadata)
        .is_some_and(|old| old != metadata)
    {
        return Err(invalid(
            "declaration metadata disagrees between cleaned occurrences",
        ));
    }
    let expected = SourceScope::new(
        payment.member_id,
        payment.declaration_id,
        payment.register_id,
    )
    .funding_entry(payment.funding_ordinal);
    if payment.funding_entry_id != expected {
        return Err(invalid(
            "funding occurrence ID disagrees with its source identity",
        ));
    }
    Ok(())
}
fn check_observation(
    observation: &Observation,
    input: &ResolutionInput,
    declarations: &mut DeclarationMetadata,
) -> Result<(), EntityIngestionError> {
    if observation.register_id == 0 {
        return Err(invalid("invalid cleaned observation identity"));
    }
    check_scope(observation, input)?;
    if observation.role != FunderRole::Donor
        && (observation.donor_kind.is_some() || observation.donor_company_number.is_some())
    {
        return Err(invalid("payer role carries donor metadata"));
    }
    if observation.address_match_quality
        != AddressMatchQuality::from_normalized(observation.address_normalized.as_deref())
    {
        return Err(invalid(
            "address matching quality disagrees with public evidence",
        ));
    }
    if observation
        .name_normalized
        .as_ref()
        .is_some_and(|name| name.trim().is_empty())
        || observation
            .person_name_normalized
            .as_ref()
            .is_some_and(|name| name.trim().is_empty())
        || observation
            .address_normalized
            .as_ref()
            .is_some_and(|address| address.trim().is_empty())
    {
        return Err(invalid("empty normalized comparison evidence"));
    }
    let expected = observation.funding_entry_id.as_ref().map_or_else(
        || {
            SourceScope::new(
                observation.member_id,
                observation.declaration_id,
                observation.register_id,
            )
            .declaration_observation(observation.role)
        },
        |id| id.observation(observation.role),
    );
    if observation.funder_id != expected {
        return Err(invalid(
            "funder observation ID disagrees with source scope and role",
        ));
    }
    let metadata = declarations
        .entry((observation.member_id, observation.declaration_id))
        .or_insert((observation.register_id, None));
    if metadata.0 != observation.register_id {
        return Err(invalid("observation declaration register mismatch"));
    }
    Ok(())
}
fn check_scope(
    observation: &Observation,
    input: &ResolutionInput,
) -> Result<(), EntityIngestionError> {
    let root = root_scope(&observation.source_pointer);
    if !root {
        return Err(invalid("malformed cleaned source pointer"));
    }
    match (
        observation.source_scope.as_str(),
        &observation.funding_entry_id,
        observation.funding_ordinal,
    ) {
        ("declaration", None, None) if is_root(&observation.source_pointer) => {}
        ("funding_entry", Some(id), Some(ordinal)) => {
            let payment = input
                .payments
                .get(id)
                .ok_or_else(|| invalid("observation has a dangling funding occurrence"))?;
            if payment.member_id != observation.member_id
                || payment.declaration_id != observation.declaration_id
                || payment.register_id != observation.register_id
                || payment.funding_ordinal != ordinal
            {
                return Err(invalid(
                    "observation scope disagrees with funding occurrence",
                ));
            }
        }
        _ => return Err(invalid("invalid observation source scope")),
    }
    Ok(())
}
use super::{
    AUTOMATIC_THRESHOLD, AddressMatchQuality, BTreeMap, BTreeSet, EntityIngestionError,
    FunderObservationId, FunderRole, IdentityBasis, Observation, ObservationResolution,
    PairDecision, PairDisposition, PairReason, ResolutionInput, ScoredPair, ScoringInput, invalid,
};
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EntityKind {
    Person,
    Organisation,
    Unknown,
}
fn kind(observation: &Observation) -> EntityKind {
    match observation
        .donor_kind
        .as_deref()
        .map(str::trim)
        .map(str::to_ascii_lowercase)
        .as_deref()
    {
        Some("individual" | "person") => EntityKind::Person,
        Some(
            "company"
            | "charity"
            | "trade union"
            | "union"
            | "other organisation"
            | "organisation"
            | "unincorporated association"
            | "registered party"
            | "trust"
            | "limited liability partnership"
            | "friendly society"
            | "building society",
        ) => EntityKind::Organisation,
        _ => EntityKind::Unknown,
    }
}
pub(super) fn individual_donor_name(observation: &Observation) -> Option<&str> {
    if observation.role != FunderRole::Donor || kind(observation) != EntityKind::Person {
        return None;
    }
    observation.person_name_normalized.as_deref()
}
pub(super) fn company(observation: &Observation) -> Option<String> {
    if observation
        .donor_kind
        .as_deref()
        .is_some_and(|kind| !kind.trim().eq_ignore_ascii_case("company"))
    {
        return None;
    }
    let number = observation
        .donor_company_number
        .as_ref()?
        .trim_matches(|c: char| c.is_ascii_whitespace())
        .to_ascii_uppercase();
    (number.len() == 8
        && number.bytes().all(|b| b.is_ascii_alphanumeric())
        && number.bytes().any(|b| b.is_ascii_digit()))
    .then_some(number)
}

#[derive(Clone, Copy)]
enum LinkEvidence {
    Statistical,
    DonorName,
    ExtractedName,
    TradeUnionFamily,
}
#[derive(Clone, Copy)]
enum EdgeEligibility {
    Link(LinkEvidence),
    Review,
    Reject(PairReason),
}
struct CandidateEdge {
    decision: PairDecision,
    eligibility: EdgeEligibility,
}
fn classify(a: &Observation, b: &Observation, probability: f64) -> EdgeEligibility {
    if kind(a) != EntityKind::Unknown && kind(b) != EntityKind::Unknown && kind(a) != kind(b) {
        return EdgeEligibility::Reject(PairReason::PersonOrganisationConflict);
    }
    let exact_name = a.name_normalized.is_some() && a.name_normalized == b.name_normalized;
    let full_addresses = a.address_match_quality == AddressMatchQuality::NumberedStreet
        && b.address_match_quality == AddressMatchQuality::NumberedStreet
        && a.address_normalized.is_some()
        && b.address_normalized.is_some();
    let addresses_agree = a
        .address_normalized
        .as_deref()
        .zip(b.address_normalized.as_deref())
        .is_some_and(|(left, right)| address_key(left) == address_key(right));
    let same_union_family = trade_union(a)
        && trade_union(b)
        && union_root(a.name_raw.as_deref()).is_some()
        && union_root(a.name_raw.as_deref()) == union_root(b.name_raw.as_deref());
    let extracted_name_agrees = aliases_agree(a, b)
        || (organization_compatible(a, b)
            && addresses_agree
            && representative_annotation(a, b)
            && base_name_overlap(a, b));
    if same_union_family {
        EdgeEligibility::Link(LinkEvidence::TradeUnionFamily)
    } else if exact_name && full_addresses && addresses_agree && probability >= AUTOMATIC_THRESHOLD
    {
        EdgeEligibility::Link(LinkEvidence::Statistical)
    } else if exact_name && a.role == FunderRole::Donor && b.role == FunderRole::Donor {
        EdgeEligibility::Link(LinkEvidence::DonorName)
    } else if extracted_name_agrees
        || individual_donor_name(a)
            .zip(individual_donor_name(b))
            .is_some_and(|(left, right)| left == right)
    {
        EdgeEligibility::Link(LinkEvidence::ExtractedName)
    } else if full_addresses && !addresses_agree {
        EdgeEligibility::Reject(PairReason::FullAddressDisagreement)
    } else {
        EdgeEligibility::Review
    }
}

fn trade_union(observation: &Observation) -> bool {
    observation
        .donor_kind
        .as_deref()
        .is_some_and(|kind| kind.trim().eq_ignore_ascii_case("trade union"))
}
fn organization_compatible(a: &Observation, b: &Observation) -> bool {
    let left = kind(a);
    let right = kind(b);
    !matches!(left, EntityKind::Person)
        && !matches!(right, EntityKind::Person)
        && (matches!(left, EntityKind::Organisation) || matches!(right, EntityKind::Organisation))
}
fn union_root(raw: Option<&str>) -> Option<&'static str> {
    let raw = raw?.to_lowercase();
    raw.split(|c: char| !c.is_alphanumeric())
        .any(|word| word == "unite")
        .then_some("unite")
}
fn aliases_agree(a: &Observation, b: &Observation) -> bool {
    a.alias_normalized.iter().any(|alias| {
        b.alias_normalized.iter().any(|other| alias == other)
            || b.name_normalized.as_ref() == Some(alias)
    }) || b
        .alias_normalized
        .iter()
        .any(|alias| a.name_normalized.as_ref() == Some(alias))
}
fn address_key(value: &str) -> String {
    value
        .chars()
        .flat_map(char::to_lowercase)
        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}
fn representative_annotation(a: &Observation, b: &Observation) -> bool {
    [a, b].iter().any(|observation| {
        let Some(qualifier) = observation
            .name_raw
            .as_deref()
            .and_then(|name| name.split_once('(').map(|(_, qualifier)| qualifier))
        else {
            return false;
        };
        let words = qualifier
            .split(|character: char| !character.is_alphanumeric())
            .filter(|word| !word.is_empty())
            .map(str::to_ascii_lowercase)
            .collect::<BTreeSet<_>>();
        [
            "ceo",
            "cfo",
            "cto",
            "cmo",
            "director",
            "chair",
            "chairman",
            "chairwoman",
            "president",
        ]
        .iter()
        .any(|title| words.contains(*title))
            || (words.contains("chief") && words.contains("executive"))
    })
}
fn base_name_overlap(a: &Observation, b: &Observation) -> bool {
    let tokens = |observation: &Observation| {
        let raw_tokens = observation
            .name_raw
            .as_deref()
            .unwrap_or("")
            .split('(')
            .next()
            .unwrap_or("")
            .split(|c: char| !c.is_alphanumeric())
            .filter(|word| !word.is_empty())
            .map(str::to_lowercase);
        let core_tokens = observation
            .organisation_core
            .as_deref()
            .unwrap_or("")
            .split_whitespace()
            .map(str::to_owned);
        raw_tokens
            .chain(core_tokens)
            .filter(|word| {
                !["the", "and", "limited", "ltd", "plc", "bank"].contains(&word.as_str())
            })
            .collect::<BTreeSet<_>>()
    };
    let left = tokens(a);
    let right = tokens(b);
    left.len() >= 2 && right.len() >= 2 && left.intersection(&right).count() >= 2
}
type CandidateEdges = BTreeMap<(FunderObservationId, FunderObservationId), CandidateEdge>;
fn expanded_edges(
    input: &ResolutionInput,
    scoring: &ScoringInput,
    pairs: Vec<ScoredPair>,
) -> Result<CandidateEdges, EntityIngestionError> {
    let mut edges = BTreeMap::new();
    for pair in pairs {
        for left in &scoring.members[&pair.left] {
            for right in &scoring.members[&pair.right] {
                if left == right {
                    continue;
                }
                let (left, right) = if left < right {
                    (left, right)
                } else {
                    (right, left)
                };
                let a = &input.observations[left];
                let b = &input.observations[right];
                if company(a).is_some() && company(b).is_some() {
                    continue;
                }
                edges
                    .entry((left.clone(), right.clone()))
                    .or_insert_with(|| CandidateEdge {
                        eligibility: classify(a, b, pair.probability),
                        decision: PairDecision {
                            left_funder_id: left.clone(),
                            right_funder_id: right.clone(),
                            probability: pair.probability,
                            name_level: pair.name_level,
                            address_level: pair.address_level,
                            disposition: PairDisposition::Review,
                            reason: PairReason::InsufficientExactEvidence,
                        },
                    });
                if edges.len() > scoring.candidate_budget {
                    return Err(invalid(
                        "expanded observation pairs exceed candidate budget; raise candidate_budget explicitly",
                    ));
                }
            }
        }
    }
    Ok(edges)
}
struct Components {
    members: Vec<BTreeSet<FunderObservationId>>,
    group: BTreeMap<FunderObservationId, usize>,
}
impl Components {
    fn new(input: &ResolutionInput) -> Self {
        let mut components: Vec<BTreeSet<FunderObservationId>> = Vec::new();
        let mut anchors = BTreeMap::<String, usize>::new();
        let mut group = BTreeMap::new();
        for observation in input.observations.values() {
            let index = if let Some(number) = company(observation) {
                *anchors.entry(number).or_insert_with(|| {
                    components.push(BTreeSet::new());
                    components.len() - 1
                })
            } else {
                components.push(BTreeSet::new());
                components.len() - 1
            };
            components[index].insert(observation.funder_id.clone());
            group.insert(observation.funder_id.clone(), index);
        }
        Self {
            members: components,
            group,
        }
    }
    fn apply(&mut self, input: &ResolutionInput, edges: &mut CandidateEdges) {
        let mut unanchored = Self::new(input);
        for edge in edges
            .values()
            .filter(|edge| matches!(edge.eligibility, EdgeEligibility::Link(_)))
        {
            let edge = &edge.decision;
            if company(&input.observations[&edge.left_funder_id]).is_none()
                && company(&input.observations[&edge.right_funder_id]).is_none()
            {
                unanchored.join(&edge.left_funder_id, &edge.right_funder_id);
            }
        }
        let mut candidate_companies = BTreeMap::<usize, BTreeSet<String>>::new();
        for candidate in edges
            .values()
            .filter(|edge| matches!(edge.eligibility, EdgeEligibility::Link(_)))
        {
            let edge = &candidate.decision;
            for (unknown, known) in [
                (&edge.left_funder_id, &edge.right_funder_id),
                (&edge.right_funder_id, &edge.left_funder_id),
            ] {
                if company(&input.observations[unknown]).is_none()
                    && let Some(number) = company(&input.observations[known])
                {
                    candidate_companies
                        .entry(unanchored.group[unknown])
                        .or_default()
                        .insert(number);
                }
            }
        }
        for candidate in edges.values_mut() {
            let edge = &mut candidate.decision;
            let evidence = match candidate.eligibility {
                EdgeEligibility::Reject(reason) => {
                    edge.disposition = PairDisposition::Rejected;
                    edge.reason = reason;
                    continue;
                }
                EdgeEligibility::Review => continue,
                EdgeEligibility::Link(evidence) => evidence,
            };
            let ambiguous_attachment = [
                (&edge.left_funder_id, &edge.right_funder_id),
                (&edge.right_funder_id, &edge.left_funder_id),
            ]
            .iter()
            .any(|(unknown, known)| {
                company(&input.observations[*unknown]).is_none()
                    && company(&input.observations[*known]).is_some()
                    && candidate_companies
                        .get(&unanchored.group[*unknown])
                        .is_some_and(|numbers| numbers.len() > 1)
            });
            if ambiguous_attachment {
                edge.reason = PairReason::CompetingCompanyAnchors;
                continue;
            }
            let left = self.group[&edge.left_funder_id];
            let right = self.group[&edge.right_funder_id];
            let ids = self.members[left]
                .union(&self.members[right])
                .cloned()
                .collect::<BTreeSet<_>>();
            let companies = ids
                .iter()
                .filter_map(|id| company(&input.observations[id]))
                .collect::<BTreeSet<_>>();
            let kinds = ids
                .iter()
                .map(|id| kind(&input.observations[id]))
                .collect::<Vec<_>>();
            if companies.len() > 1
                || (kinds.contains(&EntityKind::Person)
                    && kinds.contains(&EntityKind::Organisation))
            {
                edge.disposition = PairDisposition::Rejected;
                edge.reason = PairReason::ComponentIdentityConflict;
                continue;
            }
            self.join(&edge.left_funder_id, &edge.right_funder_id);
            edge.disposition = PairDisposition::Accepted;
            edge.reason = match evidence {
                LinkEvidence::Statistical => PairReason::ExactNameFullAddressThreshold,
                LinkEvidence::DonorName => PairReason::ExactDonorName,
                LinkEvidence::ExtractedName => PairReason::ExtractedNameEvidence,
                LinkEvidence::TradeUnionFamily => PairReason::TradeUnionFamily,
            };
        }
    }
    fn join(&mut self, left_id: &FunderObservationId, right_id: &FunderObservationId) {
        let left = self.group[left_id];
        let right = self.group[right_id];
        if left != right {
            let members = std::mem::take(&mut self.members[right]);
            for id in &members {
                self.group.insert(id.clone(), left);
            }
            self.members[left].extend(members);
        }
    }
    fn outcomes(
        &self,
        input: &ResolutionInput,
        edges: &CandidateEdges,
        run_key: &str,
    ) -> Vec<ObservationResolution> {
        let mut statistical = Self::new(input);
        let mut statistical_groups = BTreeSet::new();
        let mut extracted_groups = BTreeSet::new();
        let mut union_groups = BTreeSet::new();
        for candidate in edges.values() {
            if candidate.decision.disposition != PairDisposition::Accepted {
                continue;
            }
            let edge = &candidate.decision;
            match candidate.eligibility {
                EdgeEligibility::Link(LinkEvidence::Statistical) => {
                    statistical.join(&edge.left_funder_id, &edge.right_funder_id);
                    statistical_groups.insert(self.group[&edge.left_funder_id]);
                }
                EdgeEligibility::Link(LinkEvidence::ExtractedName) => {
                    extracted_groups.insert(self.group[&edge.left_funder_id]);
                }
                EdgeEligibility::Link(LinkEvidence::TradeUnionFamily) => {
                    union_groups.insert(self.group[&edge.left_funder_id]);
                }
                EdgeEligibility::Link(LinkEvidence::DonorName)
                | EdgeEligibility::Review
                | EdgeEligibility::Reject(_) => {}
            }
        }
        let mut observations = Vec::new();
        for observation in input.observations.values() {
            let ids = &self.members[self.group[&observation.funder_id]];
            let statistical_connected = ids
                .iter()
                .map(|id| statistical.group[id])
                .collect::<BTreeSet<_>>()
                .len()
                == 1;
            let component_basis = if statistical_connected {
                IdentityBasis::StatisticalLink
            } else if statistical_groups.contains(&self.group[&observation.funder_id]) {
                if union_groups.contains(&self.group[&observation.funder_id])
                    || extracted_groups.contains(&self.group[&observation.funder_id])
                {
                    IdentityBasis::StatisticalAndSupportingNameLink
                } else {
                    IdentityBasis::StatisticalAndDonorNameLink
                }
            } else if union_groups.contains(&self.group[&observation.funder_id]) {
                IdentityBasis::TradeUnionFamilyLink
            } else if extracted_groups.contains(&self.group[&observation.funder_id]) {
                IdentityBasis::ExtractedNameLink
            } else {
                IdentityBasis::DonorNameLink
            };
            let number = ids.iter().find_map(|id| company(&input.observations[id]));
            let (identity_id, identity_basis) = number.map_or_else(
                || {
                    if observation.name_normalized.is_none() {
                        (None, IdentityBasis::Unresolved)
                    } else {
                        let leader = ids
                            .first()
                            .expect("each observation belongs to a nonempty component")
                            .as_str();
                        (
                            Some(format!("run-local:{run_key}:{leader}")),
                            if ids.len() > 1 {
                                component_basis
                            } else {
                                IdentityBasis::ProvisionalSingleton
                            },
                        )
                    }
                },
                |number| {
                    (
                        Some(format!("source-reported:companies-house:{number}")),
                        if company(observation).is_some() {
                            IdentityBasis::SourceReportedCompany
                        } else {
                            component_basis
                        },
                    )
                },
            );
            observations.push(ObservationResolution {
                funder_id: observation.funder_id.clone(),
                identity_id,
                identity_basis,
            });
        }
        observations
    }
}
pub(super) fn resolve(
    input: &ResolutionInput,
    scoring: &ScoringInput,
    pairs: Vec<ScoredPair>,
    run_key: &str,
) -> Result<(Vec<ObservationResolution>, Vec<PairDecision>), EntityIngestionError> {
    let mut edges = expanded_edges(input, scoring, pairs)?;
    let mut components = Components::new(input);
    components.apply(input, &mut edges);
    Ok((
        components.outcomes(input, &edges, run_key),
        edges.into_values().map(|edge| edge.decision).collect(),
    ))
}
