            &[
                "AUTOMATIC_THRESHOLD",
                "IdentityBasis",
                "ObservationResolution",
                "PairDisposition",
                "PairReason",
                "PairDecision",
                "AttributionBasis",
                "UnavailableReason",
                "AttributionIssue",
                "AttributionDecision",
                "PaymentAttribution",
